<?php declare(strict_types=1);
/** Real tariff originals, a source-bound booked price and a deliberately later price. */
function recoveryTariffOriginal(PDO $db):array
{
    $db->exec("INSERT INTO clubs VALUES('own-tariff-recovery','Own tariff recovery');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-tariff-recovery-admin','own-tariff-recovery','members',1)");
    $actor='own-tariff-recovery-admin';$requests=new \Kulturhus\Verein\Settings\CatalogRequests($db,$actor);$repo=new \Kulturhus\Verein\Settings\CatalogRepository($db,$actor);$settings=new \Kulturhus\Verein\Settings($db,$actor);$registry=new \Kulturhus\Verein\Registry($db,$actor);$person=$registry->saveContact(null,0,'person','Own unchanged recovery tariff person','tariff-recovery@example.invalid','Own original address',['birthday'=>'2000-01-01']);$originals=[];$ids=[];
    foreach(['service','contribution','donation','service']as$index=>$kind){
        $state=$index===3?$repo->state($ids['service'],'service'):$repo->state('',$kind);$data=$state['data'];$data['name']=$index===3?'0':str_repeat('ä',159).$index;$data['description']=$index===3?'0':str_repeat('🙂',2000);$data['amount']='29.00';$data['tags']='0';$data['purpose']='**0** {{BEZEICHNUNG}}';$data['interval']=$kind==='service'?'month':'year';
        if($kind==='service'){$data['pricing']='age';$data['tiers']=[['from'=>'18','amount'=>$index===3?'30,00':'15,00'],['from'=>'0','amount'=>'0']];}
        $input=['id'=>$state['id'],'kind'=>$kind,'version'=>(string)$state['version'],'data'=>$data];$plan=$requests->prepare($input);$requestKey=bin2hex(random_bytes(16));$receipt=$requests->accept($input,$requestKey,$plan['hash'],true);$originals[]=$receipt;$ids[$kind]=$receipt['result']['id'];
        if($index===0){$settings->assign($ids['service'],$person,'2020-01-01','');$q=$db->prepare('SELECT id FROM catalog_assignments WHERE club_id=? AND catalog_id=?');$q->execute(['own-tariff-recovery',$ids['service']]);$assignment=$q->fetchColumn();$quote=(new \Kulturhus\Verein\CatalogBilling($db,$actor))->review([$assignment],'2026-10-20')[0];$entries=(new \Kulturhus\Verein\Finance($db,$actor))->createCatalogCharges([['assignment_id'=>$assignment,'fingerprint'=>$quote['fingerprint']]],'2026-10-20','2026-11-20','full',null,bin2hex(random_bytes(16)));$entry=(new \Kulturhus\Verein\Finance($db,$actor))->entry($entries[0]);}
    }
    $current=[];foreach($ids as$kind=>$id)$current[$kind]=$repo->state($id,$kind);
    return['originals'=>$originals,'current'=>$current,'ids'=>$ids,'first_revision'=>$repo->revision($ids['service'],'service','1'),'entry'=>$entry,'assignment'=>$assignment,'current_quote'=>(new \Kulturhus\Verein\CatalogPricing($db,$actor))->quote($assignment,'2026-10-20')];
}
