    $code=<<<'PROOF'
ini_set('zend.exception_ignore_args','1');$f=json_decode(stream_get_contents(STDIN),true,64,JSON_THROW_ON_ERROR);require $f['app'].'/vereinsverwaltung/native/bootstrap.php';require $f['app'].'/vereinsverwaltung/src/bootstrap.php';require $f['app'].'/vereinsverwaltung/tests/support/original-database-hash.php';$db=new PDO($f['dsn'],$f['username'],$f['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$before=ownOriginalDatabaseHash($db,$tables);$actor='own-tariff-recovery-admin';$requests=new \Kulturhus\Verein\Settings\CatalogRequests($db,$actor);$repo=new \Kulturhus\Verein\Settings\CatalogRepository($db,$actor);$originals=[];$same=true;foreach($f['original']['originals']as$offered){$read=$requests->receipt($offered['key']);$originals[]=$read;$same=$same&&$requests->accept($read['input'],$read['key'],$read['review']['hash'],true)===$read;}$current=[];foreach($f['original']['ids']as$kind=>$id)$current[$kind]=$repo->state($id,$kind);$paths=[];foreach([\Kulturhus\Verein\Settings\CatalogRequests::class,\Kulturhus\Verein\Settings\CatalogValues::class,\Kulturhus\Verein\Settings\CatalogRepository::class]as$class)$paths[]=(new ReflectionClass($class))->getFileName();echo json_encode(['originals'=>$originals,'same'=>$same,'current'=>$current,'first_revision'=>$repo->revision($f['original']['ids']['service'],'service','1'),'entry'=>(new \Kulturhus\Verein\Finance($db,$actor))->entry($f['original']['entry']['id']),'current_quote'=>(new \Kulturhus\Verein\CatalogPricing($db,$actor))->quote($f['original']['assignment'],'2026-10-20'),'unchanged'=>ownOriginalDatabaseHash($db,$tables)===$before,'paths'=>$paths],JSON_THROW_ON_ERROR|JSON_PRESERVE_ZERO_FRACTION);
PROOF;
    $process=proc_open([...\Kulturhus\Native\TestSupport::phpCommand(),'-r',$code],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$app);if(!is_resource($process))throw new RuntimeException('Independent tariff recovery unavailable.');fwrite($pipes[0],json_encode(['app'=>$app,'dsn'=>$dsn,'username'=>$fixture['username'],'password'=>$fixture['password'],'original'=>$original],JSON_THROW_ON_ERROR));fclose($pipes[0]);$output=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0)throw new RuntimeException('Recovered tariff originals failed: '.substr($error,0,900));$proof=json_decode($output,true,64,JSON_THROW_ON_ERROR);
    recoveryCheck($proof['originals']===$original['originals']&&$proof['same'],'independent restored tariff reads retain all first service contribution donation and later change originals without repeating a canonical save');
    recoveryCheck($proof['current']===$original['current']&&$proof['first_revision']===$original['first_revision'],'restored tariffs retain their complete first raw revision full Unicode original tiers and distinct later current literal zero values');
    recoveryCheck($proof['entry']===$original['entry']&&(int)$proof['entry']['amount_cents']===1500&&$proof['current_quote']===$original['current_quote']&&$proof['current_quote']['amount_cents']===3000,'actual relocated booked tariff price remains exactly fifteen euros while its deliberately later current quote is independently thirty euros');
    recoveryCheck($proof['unchanged']&&count(array_filter($proof['paths'],static fn(string $path):bool=>str_starts_with($path,$app.'/vereinsverwaltung/src/')))===3,'independent tariff helpers execute from the actual recovered package and preserve every complete restored business row');
}
